9	import type { AnimationFrameHandler } from "./animation-frame-handler";
10	import type App from "./components/App";
11	import type { SocketId } from "./types";
12	
13	export class LaserTrails implements Trail {
14	  public localTrail: AnimatedTrail;
15	  private collabTrails = new Map<SocketId, AnimatedTrail>();
16	
17	  private container?: SVGSVGElement;
18	
19	  constructor(
20	    private animationFrameHandler: AnimationFrameHandler,
21	    private app: App,
22	  ) {
23	    this.animationFrameHandler.register(this, this.onFrame.bind(this));
24	
25	    this.localTrail = new AnimatedTrail(animationFrameHandler, app, {
26	      ...this.getTrailOptions(),
27	      fill: () => DEFAULT_LASER_COLOR,
28	    });
29	  }
30	
31	  private getTrailOptions() {
32	    return {
33	      simplify: 0,
34	      streamline: 0.4,
35	      sizeMapping: (c) => {
36	        const DECAY_TIME = 1000;
37	        const DECAY_LENGTH = 50;
38	        const t = Math.max(
39	          0,
40	          1 - (performance.now() - c.pressure) / DECAY_TIME,
41	        );
42	        const l =
43	          (DECAY_LENGTH -
44	            Math.min(DECAY_LENGTH, c.totalLength - c.currentIndex)) /
45	          DECAY_LENGTH;
46	
47	        return Math.min(easeOut(l), easeOut(t));
48	      },
49	    } as Partial<LaserPointerOptions>;
50	  }
51	
52	  startPath(x: number, y: number): void {
53	    this.localTrail.startPath(x, y);
54	  }
55	
56	  addPointToPath(x: number, y: number): void {
57	    this.localTrail.addPointToPath(x, y);
58	  }
59	
60	  endPath(): void {
61	    this.localTrail.endPath();
62	  }
63	
64	  start(container: SVGSVGElement) {
65	    this.container = container;
66	
67	    this.animationFrameHandler.start(this);
68	    this.localTrail.start(container);
69	  }
70	
71	  stop() {
72	    this.animationFrameHandler.stop(this);
73	    this.localTrail.stop();
74	  }
75	
76	  onFrame() {
77	    this.updateCollabTrails();
78	  }
79	
80	  private updateCollabTrails() {
81	    if (!this.container || this.app.state.collaborators.size === 0) {
82	      return;
83	    }
84	
85	    for (const [key, collaborator] of this.app.state.collaborators.entries()) {
86	      let trail!: AnimatedTrail;
87	
88	      if (!this.collabTrails.has(key)) {
89	        trail = new AnimatedTrail(this.animationFrameHandler, this.app, {
